<template><main class="page"><section class="hero"><div class="wrap"><div class="crumb"><NuxtLink to="/spec-library">Spec Library</NuxtLink> / <NuxtLink to="/spec-library/engine-lathes">Engine Lathes, Mills &amp; Drills</NuxtLink> / <NuxtLink :to="'/spec-library/'+maker?.slug+'/engine-lathes'">{{maker?.name}}</NuxtLink> / {{model?.name}}</div><h1>{{maker?.name}} {{model?.name}} Specifications</h1><p>Historical specifications shown separately by year and recorded configuration.</p></div></section><section v-if="model" class="wrap section"><article v-for="(v,idx) in model.years" :key="idx" class="variant"><h2>{{v[0]||'Year not recorded'}} {{maker.name}} {{model.name}}</h2><p class="type">{{model.type}} · {{v[1]}}</p><dl><template v-for="(sp,sidx) in v[2]" :key="sidx"><dt>{{sp[0]}}</dt><dd>{{sp[1]}}</dd></template></dl><p v-if="v[3]" class="history">{{v[3]}}</p></article></section><section v-else class="wrap section"><h2>Model not found</h2><NuxtLink to="/spec-library/engine-lathes">Return to library</NuxtLink></section></main></template>
<script setup>
import a from '~/assets/data/engine-library-a-c.js';import d from '~/assets/data/engine-library-d-h.js';import i from '~/assets/data/engine-library-i-m.js';import n from '~/assets/data/engine-library-n-r.js';import s from '~/assets/data/engine-library-s-t.js';import u from '~/assets/data/engine-library-u-z.js';import {mergeSpecLibrary} from '~/utils/mergeSpecLibrary'
const route=useRoute(),library=mergeSpecLibrary([a,d,i,n,s,u]);const maker=computed(()=>library.find(x=>x.slug===route.params.manufacturer));const model=computed(()=>maker.value?.models.find(x=>x.slug===route.params.model));useSeoMeta({title:()=>maker.value&&model.value?`${maker.value.name} ${model.value.name} Specifications | UMS`:'Machine Specifications | UMS',description:()=>maker.value&&model.value?`Historical ${maker.value.name} ${model.value.name} conventional machine specifications by year and configuration.`:'Historical machine specifications.'})
</script><style scoped>.page{color:#17273a}.wrap{max-width:1100px;margin:auto;padding:0 28px}.hero{background:#0b2545;color:#fff;padding:42px 0;border-bottom:4px solid #f47b20}.crumb,.crumb a{color:#c9d8e8}.section{padding-top:38px}.variant{border:1px solid #d7e0e8;border-radius:8px;padding:22px;margin-bottom:22px}.variant h2{color:#0b2545;margin-top:0}.type,.history{color:#68798a}dl{display:grid;grid-template-columns:minmax(180px,35%) 1fr;border-top:1px solid #e2e8ef}dt,dd{margin:0;padding:9px 10px;border-bottom:1px solid #e2e8ef}dt{font-weight:800;background:#f7f9fb}@media(max-width:700px){dl{grid-template-columns:1fr}dt{border-bottom:0}}</style>